#pragma once


// Haiku's MIME database as a table (MimeTable.cpp, generated by
// tools/mime/generate-mime-table.py from Haiku's src/data/mime_db).


#include <array>
#include <string_view>


namespace ngui::detail {


struct MimeTableEntry {
	std::string_view	type;				// META:TYPE
	std::string_view	shortDescription;	// META:S:DESC
	std::string_view	extensions;			// META:EXTENS, separated by spaces
	std::string_view	icon;				// the system icon (data/icons/haiku/), or none
};


extern const std::array<MimeTableEntry, 177> kMimeTable;


} // namespace ngui::detail
